public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { cloudId, datastoreType, businessID, measurementId, region } = dbAccessInformation;

        if (datastoreType === SupportedDatastores.s3) {
            const awsRegion = region || process.env.AWS_REGION || 'us-east-1';
            const iamClient = new IAMClient({ region: awsRegion });
            const roleName = `datastore-${businessID}-${measurementId}`;

            // Generate a unique external ID
            const externalId = randomUUID();

            // Create trust policy document
            const trustPolicy = {
                Version: '2012-10-17',
                Statement: [
                    {
                        Effect: 'Allow',
                        Principal: {
                            AWS: `arn:aws:iam::${cloudId}:root`,
                        },
                        Action: 'sts:AssumeRole',
                        Condition: {
                            StringEquals: {
                                'sts:ExternalId': externalId,
                            },
                        },
                    },
                ],
            };

            // Create permission policy document
            const ingestionPrefix = `${businessID}/${measurementId}/ingestion`;
            const dlqPrefix = `${businessID}/${measurementId}/dlq`;

            const permissionPolicy = {
                Version: '2012-10-17',
                Statement: [
                    {
                        Effect: 'Allow',
                        Action: ['s3:GetObject', 's3:PutObject', 's3:ListBucket'],
                        Resource: [
                            `arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
                            `arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${ingestionPrefix}/*`,
                        ],
                    },
                    {
                        Effect: 'Allow',
                        Action: ['s3:GetObject', 's3:PutObject', 's3:ListBucket'],
                        Resource: [
                            `arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`,
                            `arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${dlqPrefix}/*`,
                        ],
                    },
                ],
            };

            try {
                // Create the IAM role
                const createRoleCommand = new CreateRoleCommand({
                    RoleName: roleName,
                    AssumeRolePolicyDocument: JSON.stringify(trustPolicy),
                    Description: `Paigo datastore measurement role for business ${businessID}, measurement ${measurementId}`,
                    MaxSessionDuration: 3600,
                });
                const roleResponse = await iamClient.send(createRoleCommand);
                const iamRoleArn = roleResponse.Role?.Arn;

                if (!iamRoleArn) {
                    throw new InternalServerErrorException('Failed to create IAM role: no ARN returned');
                }

                // Attach the permission policy to the role
                const putRolePolicyCommand = new PutRolePolicyCommand({
                    RoleName: roleName,
                    PolicyName: `PaigoDatastoreAccess-${businessID}-${measurementId}`,
                    PolicyDocument: JSON.stringify(permissionPolicy),
                });
                await iamClient.send(putRolePolicyCommand);

                // Update the dbAccessInformation with the generated values
                dbAccessInformation.iamRoleArn = iamRoleArn;
                dbAccessInformation.externalId = externalId;
                dbAccessInformation.ingestion = ingestionPrefix;
                dbAccessInformation.dlq = dlqPrefix;
            } catch (e) {
                if (e instanceof NoSuchEntityException || e?.Code === 'MalformedPolicy') {
                    throw new BadRequestException(`CloudId: ${cloudId} is invalid`);
                } else if (e?.Code === 'EntityAlreadyExists') {
                    throw new BadRequestException(`IAM role ${roleName} already exists`);
                } else {
                    throw e;
                }
            }
        }
    }

    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { cloudId, datastoreType, businessID, measurementId, iamRoleArn, externalId, region } = dbAccessInformation;

        if (datastoreType === SupportedDatastores.s3 && iamRoleArn && externalId) {
            const awsRegion = region || process.env.AWS_REGION || 'us-east-1';
            const iamClient = new IAMClient({ region: awsRegion });
            const roleName = `datastore-${businessID}-${measurementId}`;

            // Update trust policy with new cloudId but preserve externalId
            const trustPolicy = {
                Version: '2012-10-17',
                Statement: [
                    {
                        Effect: 'Allow',
                        Principal: {
                            AWS: `arn:aws:iam::${cloudId}:root`,
                        },
                        Action: 'sts:AssumeRole',
                        Condition: {
                            StringEquals: {
                                'sts:ExternalId': externalId,
                            },
                        },
                    },
                ],
            };

            try {
                // Update the assume role policy
                const updateAssumeRolePolicyCommand = new UpdateAssumeRolePolicyCommand({
                    RoleName: roleName,
                    PolicyDocument: JSON.stringify(trustPolicy),
                });
                await iamClient.send(updateAssumeRolePolicyCommand);
            } catch (e) {
                if (e instanceof NoSuchEntityException) {
                    throw new BadRequestException(`IAM role ${roleName} not found`);
                } else if (e?.Code === 'MalformedPolicy') {
                    throw new BadRequestException(`CloudId: ${cloudId} is invalid`);
                } else {
                    throw e;
                }
            }
        }
    }

